            ${'$'}name: String
        ) {
            accountCreate(
                email: ${'$'}email,
                password: ${'$'}password,
                name: ${'$'}name,
                userId: "unique()"
            ) {
                _id
            }
        }""",
        "variables" to mapOf(
            "email" to "...",
            "password" to "...",
            "name" to "..."
        )
