## Query methods

Now that we have a table in the database to hold ideas, we can connect to it from our app.
Our users should be able to read, add and remove ideas.
We will add a new hook, `useIdeas`, to handle this functionality.

Create a new file `hooks/useIdeas.ts` and add the following code.

```ts
// hooks/useIdeas.ts

import { useState, useEffect } from 'react';
import { ID, Query, Permission, type Models } from 'appwrite';
import { tablesDB } from '../lib/appwrite';

const databaseId = process.env.NEXT_PUBLIC_DATABASE_ID!;
const tableId = process.env.NEXT_PUBLIC_TABLE_ID!;
const queryLimit = 10;

interface Idea extends Models.Row {
    title: string;
    description: string;
    userId: string;
}

export function useIdeas() {
    const [current, setCurrent] = useState<Idea[]>([]);
    const [loading, setLoading] = useState(true);

    // Fetch the 10 most recent ideas from the database
    const fetch = async (): Promise<void> => {
        try {
            const response = await tablesDB.listRows({
                databaseId,
                tableId,
                queries: [Query.orderDesc('$createdAt'), Query.limit(queryLimit)]
            });
            setCurrent(response.rows as Idea[]);
        } catch (error) {
            console.error('Error fetching ideas:', error);
        } finally {
            setLoading(false);
        }
    };

    // Add new idea to the database
    const add = async (idea: Omit<Idea, '$id' | '$createdAt' | '$updatedAt' | '$permissions'>): Promise<void> => {
        try {
            const response = await tablesDB.createRow({
                databaseId,
                tableId,
                rowId: ID.unique(),
                data: idea,
                permissions: [
                    Permission.read('any'),
                    Permission.update(`user:${idea.userId}`),
                    Permission.delete(`user:${idea.userId}`)
                ]
            });
            setCurrent(prev => [response as Idea, ...prev].slice(0, queryLimit));
        } catch (error) {
            console.error('Error adding idea:', error);
        }
    };

    const remove = async (id: string): Promise<void> => {
        try {
            await tablesDB.deleteRow({
                databaseId,
                tableId,
                rowId: id
            });
            await fetch(); // Refetch ideas to ensure we have 10 items
        } catch (error) {
            console.error('Error removing idea:', error);
        }
    };

    useEffect(() => {
        fetch();
    }, []);

    return {
        current,
        loading,
        add,
        fetch,
        remove,
    };
}
```

Now we can call the `useIdeas()` hook from the home page.

With the methods in the `useIdeas()` hook we can get some ideas to the home page for the users to interact with.
We will use it in a form component so the logged in users can add their ideas, and in a list component to render the ten most recent ideas.
We start with building the form.

## Idea form

On the home page, the logged in users should be able to add their ideas to the Appwrite database.
The form needs a text field for filling in the title, a textarea for the description and a submit button.

Create a new file `src/components/IdeasForm.tsx` and add the following code.

```tsx
// src/components/IdeasForm.tsx
'use client';

import { useIdeas } from '../hooks/useIdeas';
import { useAuth } from '../hooks/useAuth';

export default function IdeasForm() {
    const { add } = useIdeas();
    const { current: user } = useAuth();

    const handleAddIdea = async (event: React.FormEvent<HTMLFormElement>) => {
        event.preventDefault();
        const form = event.target as HTMLFormElement;
        const formData = new FormData(form);

        if (!user) return;

        const postIdeaData = {
            userId: user.userId,
            title: formData.get('title') as string,
            description: formData.get('description') as string,
        };

        await add(postIdeaData);
        form.reset();
    };

    if (!user) {
        return null; // Don't render form if user is not logged in
    }

    return (
        <div>
            <article className="container padding-0">
                <h4 className="heading-level-4">Submit Idea</h4>
                <form onSubmit={handleAddIdea} className="u-margin-block-start-16">
                    <ul className="form-list">
                        <li className="form-item">
                            <label className="label">Title</label>
                            <input
                                type="text"
                                placeholder="Title"
                                name="title"
                                required
                            />
                        </li>
                        <li className="form-item">
                            <label className="label">Description</label>
                            <textarea
                                placeholder="Description"
                                name="description"
                                rows={4}
                            />
                        </li>
                    </ul>
                    <ul className="buttons-list u-margin-block-start-16">
                        <li className="buttons-list-item">
                            <button
                                type="submit"
                                className="button"
                                aria-label="Submit idea"
                            >
                                Submit
                            </button>
                        </li>
                    </ul>
                </form>
            </article>
        </div>
    );
}
```

## Ideas list

Now we need to display the ideas from the database. Create a new file `src/components/IdeasList.tsx`.

```tsx
// src/components/IdeasList.tsx
'use client';

import { useIdeas } from '../hooks/useIdeas';
import { useAuth } from '../hooks/useAuth';

export default function IdeasList() {
    const { current: ideas, loading, remove } = useIdeas();
    const { current: user } = useAuth();

    if (loading) {
        return <div>Loading ideas...</div>;
    }

    if (ideas.length === 0) {
        return (
            <div className="container u-margin-block-start-16">
                <p>No ideas yet. Be the first to share one!</p>
            </div>
        );
    }

    return (
        <div className="container u-margin-block-start-16">
            <h4 className="heading-level-4 u-margin-block-end-16">Latest Ideas</h4>
            <ul className="u-margin-0 u-padding-0">
                {ideas.map((idea) => (
                    <li key={idea.$id} className="card u-margin-block-end-16">
                        <div className="u-flex u-main-space-between">
                            <div className="u-flex-grow-1">
                                <h5 className="heading-level-5">{idea.title}</h5>
                                {idea.description && (
                                    <p className="u-margin-block-start-8">
                                        {idea.description}
                                    </p>
                                )}
                            </div>
                            {user && user.userId === idea.userId && (
                                <button
                                    onClick={() => remove(idea.$id)}
                                    className="button is-text u-padding-inline-8"
                                    aria-label="Delete idea"
                                >
                                    🗑️
                                </button>
                            )}
                        </div>
                    </li>
                ))}
            </ul>
        </div>
    );
}
```

